    12  function BaseTextInputWithCurrencySymbol(
    13      {
    14          selectedCurrencyCode,
    15          onCurrencyButtonPress = () => {},
    16          onChangeAmount = () => {},
    17          formattedAmount,
    18          placeholder,
    19          selection,
    20          onSelectionChange = () => {},
    21          onKeyPress = () => {},
    22          isCurrencyPressable = true,
    23          hideCurrencySymbol = false,
    24          extraSymbol,
    25          style,
    26          ...rest
    27      }: TextInputWithCurrencySymbolProps,
    28      ref: React.ForwardedRef<BaseTextInputRef>,
    29  ) {
    30      const {fromLocaleDigit} = useLocalize();
    31      const currencySymbol = CurrencyUtils.getLocalizedCurrencySymbol(selectedCurrencyCode);
    32      const isCurrencySymbolLTR = CurrencyUtils.isCurrencySymbolLTR(selectedCurrencyCode);
    33      const styles = useThemeStyles();
    34
    35      const currencySymbolButton = !hideCurrencySymbol && (
    36          <CurrencySymbolButton
    37              currencySymbol={currencySymbol ?? ''}
    38              onCurrencyButtonPress={onCurrencyButtonPress}
    39              isCurrencyPressable={isCurrencyPressable}
    40          />
    41      );
    42
    43      /**
    44       * Set a new amount value properly formatted
    45       *
    46       * @param text - Changed text from user input
    47       */
    48      const setFormattedAmount = (text: string) => {
    49          const newAmount = MoneyRequestUtils.addLeadingZero(MoneyRequestUtils.replaceAllDigits(text, fromLocaleDigit));
    50          onChangeAmount(newAmount);
    51      };
    52
    53      const amountTextInput = (
    54          <AmountTextInput
    55              formattedAmount={formattedAmount}
    56              onChangeAmount={setFormattedAmount}
    57              placeholder={placeholder}
    58              ref={ref}
    59              selection={selection}
    60              onSelectionChange={(event: NativeSyntheticEvent<TextInputSelectionChangeEventData>) => {
    61                  onSelectionChange(event);
    62              }}
    63              onKeyPress={onKeyPress}
    64              style={[styles.pr1, style]}
    65              // eslint-disable-next-line react/jsx-props-no-spreading
    66              {...rest}
    67          />
    68      );
    69
    70      if (isCurrencySymbolLTR) {
    71          return (
    72              <>
    73                  {currencySymbolButton}
    74                  {amountTextInput}
    75                  {extraSymbol}
    76              </>
    77          );
    78      }
    79
    80      return (
    81          <>
    82              {amountTextInput}
    83              {currencySymbolButton}
    84              {extraSymbol}
    85          </>
    86      );
    87  }
    88
    89  BaseTextInputWithCurrencySymbol.displayName = 'BaseTextInputWithCurrencySymbol';
    90
    91  export default React.forwardRef(BaseTextInputWithCurrencySymbol);

