    18  type MoneyRequestAmountInputRef = {
    19      setNewAmount: (amountValue: string) => void;
    20      changeSelection: (newSelection: Selection) => void;
    21      changeAmount: (newAmount: string) => void;
    22      getAmount: () => string;
