    47
    48      /** Style for the input */
    49      inputStyle?: StyleProp<TextStyle>;
    50
    51      /** Style for the container */
    52      containerStyle?: StyleProp<ViewStyle>;
    53
    54      /** Reference to moneyRequestAmountInputRef */
    55      moneyRequestAmountInputRef?: ForwardedRef<MoneyRequestAmountInputRef>;
    56
    57      /** Character to be shown before the amount */
    58      prefixCharacter?: string;
    59
    60      /** Whether to hide the currency symbol */
    61      hideCurrencySymbol?: boolean;
    62
    63      /** Whether to disable native keyboard on mobile */
    64      disableKeyboard?: boolean;
    65
    66      /** Style for the prefix */
    67      prefixStyle?: StyleProp<TextStyle>;
    68
    69      /** Style for the prefix container */
    70      prefixContainerStyle?: StyleProp<ViewStyle>;
    71
    72      /** Style for the touchable input wrapper */
    73      touchableInputWrapperStyle?: StyleProp<ViewStyle>;
    74
    75      /** Whether we want to format the display amount on blur */
    76      formatAmountOnBlur?: boolean;
    77
    78      /** Max length for the amount input */
    79      maxLength?: number;
    80
    81      /** Hide the focus styles on TextInput */
    82      hideFocusedState?: boolean;
    83
    84      /** Whether the user input should be kept or not */
    85      shouldKeepUserInput?: boolean;
    86
    87      /**
    88       * Autogrow input container length based on the entered text.
    89       */
    90      autoGrow?: boolean;
    91
    92      /** The width of inner content */
    93      contentWidth?: number;
    94  };
    95
    96  type Selection = {
    97      start: number;
    98      end: number;
    99  };
   100
   101  /**
   102   * Returns the new selection object based on the updated amount's length
   103   */
   104  const getNewSelection = (oldSelection: Selection, prevLength: number, newLength: number): Selection => {
   105      const cursorPosition = oldSelection.end + (newLength - prevLength);
   106      return {start: cursorPosition, end: cursorPosition};
   107  };
   108
   109  const defaultOnFormatAmount = (amount: number, currency?: string) => CurrencyUtils.convertToFrontendAmountAsString(amount, currency ?? CONST.CURRENCY.USD);
   110
   111  function MoneyRequestAmountInput(
   112      {
   113          amount = 0,
   114          currency = CONST.CURRENCY.USD,
   115          isCurrencyPressable = true,
   116          onCurrencyButtonPress,
   117          onAmountChange,
   118          prefixCharacter = '',
   119          hideCurrencySymbol = false,
   120          shouldUpdateSelection = true,
   121          moneyRequestAmountInputRef,
   122          disableKeyboard = true,
   123          onFormatAmount = defaultOnFormatAmount,
   124          formatAmountOnBlur,
   125          maxLength,
   126          hideFocusedState = true,
   127          shouldKeepUserInput = false,
   128          autoGrow = true,
   129          contentWidth,
   130          ...props
   131      }: MoneyRequestAmountInputProps,
   132      forwardedRef: ForwardedRef<BaseTextInputRef>,
   133  ) {
   134      const {toLocaleDigit, numberFormat} = useLocalize();
   135
   136      const textInput = useRef<BaseTextInputRef | null>(null);
   137
   138      const decimals = CurrencyUtils.getCurrencyDecimals(currency);
   139      const selectedAmountAsString = amount ? onFormatAmount(amount, currency) : '';
   140
   141      const [currentAmount, setCurrentAmount] = useState(selectedAmountAsString);
   142
   143      const [selection, setSelection] = useState({
   144          start: selectedAmountAsString.length,
   145          end: selectedAmountAsString.length,
   146      });
   147
   148      const forwardDeletePressedRef = useRef(false);
   149      // The ref is used to ignore any onSelectionChange event that happens while we are updating the selection manually in setNewAmount
   150      const willSelectionBeUpdatedManually = useRef(false);
   151
   152      /**
   153       * Sets the selection and the amount accordingly to the value passed to the input
   154       * @param {String} newAmount - Changed amount from user input
   155       */
   156      const setNewAmount = useCallback(
   157          (newAmount: string) => {
   158              // Remove spaces from the newAmount value because Safari on iOS adds spaces when pasting a copied value
   159              // More info: https://github.com/Expensify/App/issues/16974
   160              const newAmountWithoutSpaces = MoneyRequestUtils.stripSpacesFromAmount(newAmount);
   161              const finalAmount = newAmountWithoutSpaces.includes('.')
   162                  ? MoneyRequestUtils.stripCommaFromAmount(newAmountWithoutSpaces)
   163                  : MoneyRequestUtils.replaceCommasWithPeriod(newAmountWithoutSpaces);
   164              // Use a shallow copy of selection to trigger setSelection
   165              // More info: https://github.com/Expensify/App/issues/16385
   166              if (!MoneyRequestUtils.validateAmount(finalAmount, decimals)) {
   167                  setSelection((prevSelection) => ({...prevSelection}));
   168                  return;
   169              }
   170
   171              // setCurrentAmount contains another setState(setSelection) making it error-prone since it is leading to setSelection being called twice for a single setCurrentAmount call. This solution introducing the hasSelectionBeenSet flag was chosen for its simplicity and lower risk of future errors https://github.com/Expensify/App/issues/23300#issuecomment-1766314724.
   172
   173              willSelectionBeUpdatedManually.current = true;
   174              let hasSelectionBeenSet = false;
   175              setCurrentAmount((prevAmount) => {
   176                  const strippedAmount = MoneyRequestUtils.stripCommaFromAmount(finalAmount);
   177                  const isForwardDelete = prevAmount.length > strippedAmount.length && forwardDeletePressedRef.current;
   178                  if (!hasSelectionBeenSet) {
   179                      hasSelectionBeenSet = true;
   180                      setSelection((prevSelection) => getNewSelection(prevSelection, isForwardDelete ? strippedAmount.length : prevAmount.length, strippedAmount.length));
   181                      willSelectionBeUpdatedManually.current = false;
   182                  }
   183                  onAmountChange?.(strippedAmount);
   184                  return strippedAmount;
   185              });
   186          },
   187          [decimals, onAmountChange],
   188      );
   189
   190      useImperativeHandle(moneyRequestAmountInputRef, () => ({
   191          setNewAmount(amountValue: string) {
   192              setNewAmount(amountValue);
   193          },
   194          changeSelection(newSelection: Selection) {
   195              setSelection(newSelection);
   196          },
   197          changeAmount(newAmount: string) {
   198              setCurrentAmount(newAmount);
   199          },
   200          getAmount() {
   201              return currentAmount;
   202          },
   203          getSelection() {
   204              return selection;
   205          },
   206      }));
   207
   208      useEffect(() => {
   209          if ((!currency || typeof amount !== 'number' || (formatAmountOnBlur && isTextInputFocused(textInput))) ?? shouldKeepUserInput) {
   210              return;
   211          }
   212          const frontendAmount = onFormatAmount(amount, currency);
   213          setCurrentAmount(frontendAmount);
   214
   215          // Only update selection if the amount prop was changed from the outside and is not the same as the current amount we just computed
   216          // In the line below the currentAmount is not immediately updated, it should still hold the previous value.
   217          if (frontendAmount !== currentAmount) {
   218              setSelection({
   219                  start: frontendAmount.length,
   220                  end: frontendAmount.length,
   221              });
   222          }
   223
   224          // we want to re-initialize the state only when the amount changes
   225          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   226      }, [amount, shouldKeepUserInput]);
   227
   228      // Modifies the amount to match the decimals for changed currency.
   229      useEffect(() => {
   230          // If the changed currency supports decimals, we can return
   231          if (MoneyRequestUtils.validateAmount(currentAmount, decimals)) {
   232              return;
   233          }
   234
   235          // If the changed currency doesn't support decimals, we can strip the decimals
   236          setNewAmount(MoneyRequestUtils.stripDecimalsFromAmount(currentAmount));
   237
   238          // we want to update only when decimals change (setNewAmount also changes when decimals change).
   239          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   240      }, [setNewAmount]);
   241
   242      /**
   243       * Input handler to check for a forward-delete key (or keyboard shortcut) press.
   244       */
   245      const textInputKeyPress = ({nativeEvent}: NativeSyntheticEvent<KeyboardEvent>) => {
   246          const key = nativeEvent?.key.toLowerCase();
   247          if (Browser.isMobileSafari() && key === CONST.PLATFORM_SPECIFIC_KEYS.CTRL.DEFAULT) {
