   254          // Also check for the keyboard shortcut on iOS in cases where a hardware keyboard may be connected to the device.
   255          const operatingSystem = getOperatingSystem();
   256          forwardDeletePressedRef.current = key === 'delete' || ((operatingSystem === CONST.OS.MAC_OS || operatingSystem === CONST.OS.IOS) && nativeEvent?.ctrlKey && key === 'd');
   257      };
   258
   259      const formatAmount = useCallback(() => {
   260          if (!formatAmountOnBlur) {
   261              return;
   262          }
   263          const formattedAmount = onFormatAmount(amount, currency);
   264          if (maxLength && formattedAmount.length > maxLength) {
   265              return;
   266          }
   267          setCurrentAmount(formattedAmount);
   268          setSelection({
   269              start: formattedAmount.length,
   270              end: formattedAmount.length,
   271          });
   272      }, [amount, currency, onFormatAmount, formatAmountOnBlur, maxLength]);
   273
   274      const formattedAmount = MoneyRequestUtils.replaceAllDigits(currentAmount, toLocaleDigit);
   275
   276      const {setMouseDown, setMouseUp} = useMouseContext();
   277      const handleMouseDown = (e: React.MouseEvent<Element, MouseEvent>) => {
   278          e.stopPropagation();
   279          setMouseDown();
   280      };
   281      const handleMouseUp = (e: React.MouseEvent<Element, MouseEvent>) => {
   282          e.stopPropagation();
   283          setMouseUp();
   284      };
   285
   286      return (
   287          <TextInputWithCurrencySymbol
   288              autoGrow={autoGrow}
   289              disableKeyboard={disableKeyboard}
   290              formattedAmount={formattedAmount}
   291              onChangeAmount={setNewAmount}
   292              onCurrencyButtonPress={onCurrencyButtonPress}
   293              onBlur={formatAmount}
   294              placeholder={numberFormat(0)}
   295              ref={(ref) => {
   296                  if (typeof forwardedRef === 'function') {
   297                      forwardedRef(ref);
   298                  } else if (forwardedRef?.current) {
   299                      // eslint-disable-next-line no-param-reassign
   300                      forwardedRef.current = ref;
   301                  }
   302                  // eslint-disable-next-line react-compiler/react-compiler
   303                  textInput.current = ref;
   304              }}
   305              selectedCurrencyCode={currency}
   306              selection={selection}
   307              onSelectionChange={(e: NativeSyntheticEvent<TextInputSelectionChangeEventData>) => {
   308                  if (shouldIgnoreSelectionWhenUpdatedManually && willSelectionBeUpdatedManually.current) {
   309                      willSelectionBeUpdatedManually.current = false;
   310                      return;
   311                  }
   312                  if (!shouldUpdateSelection) {
   313                      return;
   314                  }
   315                  const maxSelection = formattedAmount.length;
   316                  const start = Math.min(e.nativeEvent.selection.start, maxSelection);
   317                  const end = Math.min(e.nativeEvent.selection.end, maxSelection);
   318                  setSelection({start, end});
   319              }}
   320              onKeyPress={textInputKeyPress}
   321              hideCurrencySymbol={hideCurrencySymbol}
   322              prefixCharacter={prefixCharacter}
   323              isCurrencyPressable={isCurrencyPressable}
   324              style={props.inputStyle}
   325              containerStyle={props.containerStyle}
   326              prefixStyle={props.prefixStyle}
   327              prefixContainerStyle={props.prefixContainerStyle}
   328              touchableInputWrapperStyle={props.touchableInputWrapperStyle}
   329              maxLength={maxLength}
   330              hideFocusedState={hideFocusedState}
   331              onMouseDown={handleMouseDown}
   332              onMouseUp={handleMouseUp}
   333              contentWidth={contentWidth}
   334          />
   335      );
   336  }
   337
   338  MoneyRequestAmountInput.displayName = 'MoneyRequestAmountInput';
   339
   340  export default React.forwardRef(MoneyRequestAmountInput);
   341  export type {CurrentMoney, MoneyRequestAmountInputProps, MoneyRequestAmountInputRef};

